function esc(v){return String(v).replaceAll("&","&amp;").replaceAll('"',"&quot;").replaceAll("<","&lt;").replaceAll(">","&gt;");}
function json(v){return JSON.stringify(v).replaceAll("<","\\u003c");}
function plain(v){return String(v).replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim();}
function limit(v,max){const s=plain(v);if(s.length<=max)return s;const cut=s.slice(0,max-1);const i=cut.lastIndexOf(" ");return `${cut.slice(0,i>max-18?i:max-1).replace(/[,:;.!?\s]+$/g,"")}…`;}
function langMenu(pathname){return `<details class="language-dropdown"><summary>Language</summary><div class="language-menu"><a href="${pathname}" lang="en" aria-current="page">English</a><a href="/ja/" lang="ja">日本語</a><a href="/es-419/" lang="es-419">Español (Latinoamérica)</a></div></details>`;}
function nav(pathname){return `<header class="site-header"><a class="brand" href="/"><span class="brand-mark">GS</span><span>GraveSeasons Wiki &amp; Guide</span></a><nav aria-label="Primary navigation"><a href="/guide-index/">Guides</a><a href="/release-date/">Release</a><a href="/gameplay/">Gameplay</a><a href="/characters/">Characters</a><a href="/locations/">Locations</a><a href="/items-database/">Items</a><a href="/faq/">FAQ</a>${langMenu(pathname)}</nav></header>`;}
function head({title,desc,url,schema,type="article"}){return `<head><meta charset="utf-8" /><meta name="viewport" content="width=device-width,initial-scale=1" /><title>${esc(limit(title,65))}</title><meta name="description" content="${esc(limit(desc,160))}" /><link rel="canonical" href="${url}" /><meta name="robots" content="index,follow,max-image-preview:large" /><meta property="og:type" content="${type}" /><meta property="og:site_name" content="GraveSeasons Wiki &amp; Guide" /><meta property="og:title" content="${esc(limit(title,65))}" /><meta property="og:description" content="${esc(limit(desc,160))}" /><meta property="og:url" content="${url}" /><script type="application/ld+json">${json(schema)}</script><link rel="stylesheet" href="/styles.css" /><meta name="google-adsense-account" content="ca-pub-9505220977121599" /><script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-9505220977121599" crossorigin="anonymous"></script></head>`;}

function newsPage(category,item){
  const [slug,title,summary,confirmed,meaning,boundary,source]=item;
  const pathname=`/news/${category.key}/${slug}/`, url=`${site}${pathname}`;
  const schema={"@context":"https://schema.org","@graph":[{"@type":"NewsArticle","headline":title,"description":summary,"datePublished":reviewed,"dateModified":reviewed,"mainEntityOfPage":url,"url":url,"inLanguage":"en","author":{"@type":"Organization","name":"GraveSeasons Wiki & Guide"},"publisher":{"@type":"Organization","name":"GraveSeasons Wiki & Guide"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":`${site}/`},{"@type":"ListItem","position":2,"name":"News","item":`${site}/news/`},{"@type":"ListItem","position":3,"name":title,"item":url}]}]};
  return `<!doctype html><html lang="en">${head({title:`${title} | Grave Seasons News`,desc:`${summary} Verified against the latest official Grave Seasons update.`,url,schema})}<body>${nav(pathname)}<main class="content-page"><nav class="breadcrumbs"><a href="/">Home</a><span>›</span><a href="/news/">News</a><span>›</span><span>${esc(category.name)}</span></nav><p class="section-label">${esc(category.name)} · July 31, 2026</p><h1>${esc(title)}</h1><p class="lead direct-answer"><strong>${esc(summary)}</strong></p><aside class="fact-box"><h2>Update snapshot</h2><ul class="check-list"><li>Topic: ${esc(category.hubName)}</li><li>Status: verified official information</li><li>Reviewed: July 31, 2026</li><li>Pre-release details may still change</li></ul></aside><section class="page-panel"><h2>What the official update confirms</h2><p>${esc(confirmed)}</p></section><section class="page-panel"><h2>What this changes for players</h2><p>${esc(meaning)}</p></section><section class="page-panel"><h2>What is not confirmed</h2><p>${esc(boundary)}</p></section><section class="page-panel source-note"><h2>Primary source</h2><p>This update was checked against the <a href="${source}" rel="noopener noreferrer">official Grave Seasons developer or Steam publication</a>. If a newer first-party announcement changes the fact, this canonical page will be revised rather than duplicated.</p></section><nav class="related-links"><a href="/${category.hub}/">${esc(category.hubName)}</a><a href="/faq/#${category.key}">Related FAQ</a><a href="/news/#${category.key}">All ${esc(category.name)}</a></nav></main><footer><p>Unofficial GraveSeasons Wiki &amp; Guide.</p></footer></body></html>\n`;
}

function faqPage(category,item){
  const [slug,q,a,detail]=item, pathname=`/faq/${category.key}/${slug}/`, url=`${site}${pathname}`;
  const source=category.key==="release"?releaseLog:category.key==="gameplay"||category.key==="characters"||category.key==="locations"?dayNightLog:category.key==="items"?releaseLog:steam;
  const schema={"@context":"https://schema.org","@graph":[{"@type":"FAQPage","url":url,"name":q,"inLanguage":"en","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":`${a} ${detail}`}}]},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":`${site}/`},{"@type":"ListItem","position":2,"name":"FAQ","item":`${site}/faq/`},{"@type":"ListItem","position":3,"name":q,"item":url}]}]};
  return `<!doctype html><html lang="en">${head({title:`${q} | Grave Seasons FAQ`,desc:`${q} ${a}`,url,schema})}<body>${nav(pathname)}<main class="content-page"><nav class="breadcrumbs"><a href="/">Home</a><span>›</span><a href="/faq/">FAQ</a><span>›</span><span>${esc(category.name)}</span></nav><p class="section-label">${esc(category.name)} · Verified July 31, 2026</p><h1>${esc(q)}</h1><p class="lead direct-answer"><strong>${esc(a)}</strong></p><aside class="fact-box"><h2>Quick answer</h2><ul class="check-list"><li>Category: ${esc(category.hubName)}</li><li>Evidence: current first-party material</li><li>Answer status: concrete and source-backed</li><li>Pre-release facts may still change</li></ul></aside><section class="page-panel"><h2>Confirmed detail</h2><p>${esc(detail)}</p></section><section class="page-panel"><h2>How to use this answer</h2><p>This answer separates a current confirmed fact from values that official material has not supplied. It can be used for planning, platform comparison, spoiler-safe browsing, or deciding which deeper guide to open without treating speculation as game data.</p></section><section class="page-panel"><h2>Verification boundary</h2><p>Exact schedules, prices, rewards, routes, item statistics, campaign identities, performance values, and launch-day behavior are included only when a primary source or repeatable retail-build test answers this specific question.</p></section><section class="page-panel source-note"><h2>Source policy</h2><p>The answer was reviewed against an <a href="${source}" rel="noopener noreferrer">official Grave Seasons source</a>. New information updates this URL in place so players and search engines do not have to choose between conflicting duplicates.</p></section><nav class="related-links"><a href="/${category.hub}/">${esc(category.hubName)}</a><a href="/faq/#${category.key}">All related FAQ</a><a href="/news/#${category.key==="technical"?"faq":category.key}">Related news</a></nav></main><footer><p>Unofficial GraveSeasons Wiki &amp; Guide.</p></footer></body></html>\n`;
}

function extractCards(html,marker){
  const block=html.match(new RegExp(`<!-- ${marker}:start -->([\\s\\S]*?)<!-- ${marker}:end -->`))?.[1]||"";
  return [...block.matchAll(/<article>[\s\S]*?<\/article>/g)].map(m=>m[0]);
}
function mergeModule(file,marker,newHtml){
  let html=fs.readFileSync(file,"utf8");
  html=html.replace(new RegExp(`\\s*<!-- ${marker}:start -->[\\s\\S]*?<!-- ${marker}:end -->`),"");
  html=html.replace("</main>",`\n      <!-- ${marker}:start -->${newHtml}<!-- ${marker}:end -->\n    </main>`);
  fs.writeFileSync(file,html);
}

for(const category of categories){
  for(const item of category.news){
    const dir=path.join(root,"news",category.key,item[0]);fs.mkdirSync(dir,{recursive:true});
    fs.writeFileSync(path.join(dir,"index.html"),newsPage(category,item));
  }
  const hubFile=path.join(root,category.hub,"index.html");
  const freshPaths=new Set(category.news.map(([slug])=>`/news/${category.key}/${slug}/`));
  const old=extractCards(fs.readFileSync(hubFile,"utf8"),`news:${category.key}`).filter(card=>![...freshPaths].some(p=>card.includes(`href="${p}"`)));
  const fresh=category.news.map(([slug,title,summary])=>`<article><h3><a href="/news/${category.key}/${slug}/">${esc(title)}</a></h3><p>${esc(summary)}</p><p><a href="/news/${category.key}/${slug}/">Read update →</a></p></article>`);
  mergeModule(hubFile,`news:${category.key}`,`<section class="page-panel news-module" data-news-category="${category.key}"><p class="section-label">Latest updates</p><h2>${esc(category.name)}</h2><div class="template-grid">${[...fresh,...old].join("")}</div><p><a href="/news/#${category.key}">Browse all ${esc(category.name.toLowerCase())}</a></p></section>`);
}

for(const category of faqCategories){
  for(const item of category.items){
    const dir=path.join(root,"faq",category.key,item[0]);fs.mkdirSync(dir,{recursive:true});
    fs.writeFileSync(path.join(dir,"index.html"),faqPage(category,item));
  }
  const hubFile=path.join(root,category.hub,"index.html");
  const freshPaths=new Set(category.items.map(([slug])=>`/faq/${category.key}/${slug}/`));
  const old=extractCards(fs.readFileSync(hubFile,"utf8"),`faq-access:${category.key}`).filter(card=>![...freshPaths].some(p=>card.includes(`href="${p}"`)));
  const fresh=category.items.map(([slug,q,a])=>`<article><h3><a href="/faq/${category.key}/${slug}/">${esc(q)}</a></h3><p>${esc(a)}</p></article>`);
  mergeModule(hubFile,`faq-access:${category.key}`,`<section class="page-panel faq-access-module" data-faq-category="${category.key}"><p class="section-label">Frequently asked questions</p><h2>${esc(category.name)}</h2><div class="template-grid">${[...fresh,...old].join("")}</div><p><a href="/faq/#${category.key}">Browse all ${esc(category.name.toLowerCase())}</a></p></section>`);
}

const newsFile=path.join(root,"news","index.html");
let newsHub=fs.readFileSync(newsFile,"utf8");
newsHub=newsHub.replace(/\s*<section class="page-panel" id="round-10-updates">[\s\S]*?<\/section><\/main>/g,"</main>");
newsHub=newsHub.replace(/\s*<!-- round10-news-hub:start -->[\s\S]*?<!-- round10-news-hub:end -->/g,"");
newsHub=newsHub.replace("</main>",`<!-- round10-news-hub:start --><section class="page-panel" id="round-10-updates"><p class="section-label">35 new verified updates</p><h2>July 31 News Expansion</h2>${categories.map(c=>`<section id="${c.key}-round-10"><h3>${esc(c.name)}</h3><div class="template-grid">${c.news.map(([slug,title,summary])=>`<article><h4><a href="/news/${c.key}/${slug}/">${esc(title)}</a></h4><p>${esc(summary)}</p></article>`).join("")}</div></section>`).join("")}</section><!-- round10-news-hub:end --></main>`);
