const faqFile=path.join(root,"faq","index.html");
let faqHub=fs.readFileSync(faqFile,"utf8");
faqHub=faqHub.replace(/\s*<section class="page-panel" id="round-10-faq">[\s\S]*?<\/section><\/main>/g,"</main>");
faqHub=faqHub.replace(/\s*<!-- round10-faq-hub:start -->[\s\S]*?<!-- round10-faq-hub:end -->/g,"");
faqHub=faqHub.replace("</main>",`<!-- round10-faq-hub:start --><section class="page-panel" id="round-10-faq"><p class="section-label">50 new independent answers</p><h2>Expanded Grave Seasons FAQ</h2><p>These additional source-backed questions extend the existing FAQ library without duplicating its original fifty URLs.</p>${faqCategories.map(c=>`<section id="${c.key}-round-10"><h3>${esc(c.name)}</h3><div class="template-grid">${c.items.map(([slug,q,a])=>`<article><h4><a href="/faq/${c.key}/${slug}/">${esc(q)}</a></h4><p>${esc(a)}</p></article>`).join("")}</div></section>`).join("")}</section><!-- round10-faq-hub:end --></main>`);
fs.writeFileSync(faqFile,faqHub);

const htmlFiles=[];
function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){if(["tools",".git"].includes(e.name))continue;const f=path.join(dir,e.name);if(e.isDirectory())walk(f);else if(e.name==="index.html")htmlFiles.push(f);}}
walk(root);
const urls=htmlFiles.map(f=>fs.readFileSync(f,"utf8")).filter(h=>!/name="robots" content="noindex,follow/.test(h)).map(h=>h.match(/<link rel="canonical" href="([^"]+)"/)?.[1]).filter(Boolean);
fs.writeFileSync(path.join(root,"sitemap.xml"),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${[...new Set(urls)].sort().map(u=>`  <url><loc>${u}</loc><lastmod>${reviewed}</lastmod></url>`).join("\n")}\n</urlset>\n`);

const report=`# Grave Seasons Round 10 — Navigation News and FAQ Expansion\n\n- Reviewed: ${reviewed}\n- Baseline canonical URLs: 271\n- New NewsArticle URLs: 35 (5 for each of 7 navigation tabs)\n- New FAQPage URLs: 50\n- Expected canonical URLs after build: 356\n- Existing 35 news and 50 FAQ URLs retained\n- Language dropdown retained on all new pages\n- Primary evidence: official Steam store, official Steam developer updates, and Perfect Garbage\n\nThe only dropdown in the live navigation is the language selector. It is not treated as a content tab, so no fake language-category news was generated.\n`;
fs.writeFileSync(path.join(root,"SEO-URL-EXPANSION-ROUND-10-2026-07-31.md"),report);
console.log(`Round 10 generated 35 news pages, 50 FAQ pages, and ${new Set(urls).size} sitemap URLs.`);
